def prospective():
    """Attest the genuine current owners before fresh scientific extraction."""
    project = Path(__file__).resolve().parents[4]
    actual = {name: sha256((project / name).read_bytes()).hexdigest()
              for name in _FILES}
    if actual != _FILES:
        raise ContractError('measurement_comparison_prospective_dependency_mismatch')
    return {'version': VERSION, 'files': actual}


def is_current_receipt(receipt, bound_descriptor):
    """Validate this exact saved release without source reads or recalculation."""
    return (type(receipt) is dict
            and set(receipt) == {'version', 'files', 'bound_descriptor'}
            and receipt['version'] == VERSION
            and type(receipt['files']) is dict
            and receipt['files'] == _FILES
            and receipt['bound_descriptor'] == bound_descriptor)
